import re, pathlib

# Scan for definition keyword variants across all files
pats = {
    'py': re.compile(r'^\s*(async\s+def\s|def\s|class\s)'),
    'rs': re.compile(r'^\s*(pub\s+)?(async\s+)?fn\s'),
    'ts': re.compile(r'^\s*(export\s+)?(async\s+)?function\s'),
}
variants = {}
for p in pathlib.Path('.').rglob('*'):
    if not p.is_file() or p.suffix not in ('.py','.rs','.ts'): continue
    for i, line in enumerate(p.read_text(errors='replace').splitlines(), 1):
        for lang, rx in pats.items():
            m = rx.match(line)
            if m:
                # record the stripped prefix shape to see variants
                key = (p.suffix, re.sub(r'[A-Za-z_].*$','', line.strip())[:24] or line.strip()[:24])
                variants.setdefault(key, [0, set()])
                variants[key][0] += 1
                if len(variants[key][1]) < 3:
                    variants[key][1].add(p.suffix + ':' + line.strip()[:60])
for k in sorted(variants):
    print(k, '->', variants[k][0], 'occurrences; e.g.', list(variants[k][1])[:2])
