python3 - <<'EOF'
import re, pathlib
from collections import Counter

# What definition keywords exist at all (concise shape check)?
shapes = Counter()
for p in pathlib.Path('.').rglob('*'):
    if not p.is_file() or p.suffix not in ('.py','.rs','.ts'): continue
    for line in p.read_text(errors='replace').splitlines():
        s = line.strip()
        for kw in ('def ', 'async def ', 'fn ', 'function ', '=>', 'class '):
            if s.startswith(kw) or (' ' + kw) in s[:40] and kw in ('def ','fn ','function '):
                shapes[(p.suffix, kw.strip())] += 1
for k, v in sorted(shapes.items()):
    print(k, v)
